(() => {
  'use strict';
  if (window.__AOC_ULTIMATE_OPERATIONS__) return;
  window.__AOC_ULTIMATE_OPERATIONS__ = true;

  const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money = (v) => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(v||0));
  let stream = null, timer = null, detector = null, lastCode = '', scanBusy = false;

  function toast(msg, type='success') {
    if (typeof window.showAdminMessage === 'function') return window.showAdminMessage(msg,type);
    const el=document.createElement('div'); el.textContent=msg; el.style.cssText='position:fixed;right:18px;bottom:18px;z-index:99999;padding:12px 16px;border-radius:12px;background:#111;color:#fff;box-shadow:0 10px 30px #0003'; document.body.appendChild(el); setTimeout(()=>el.remove(),3000);
  }
  function ensureStyle(){ if(document.getElementById('aoc-ops-style'))return; const s=document.createElement('style');s.id='aoc-ops-style';s.textContent=`
#aocOpsBtn{position:fixed;right:18px;bottom:18px;z-index:9990;border:0;border-radius:999px;padding:13px 17px;background:#111;color:#fff;font-weight:800;box-shadow:0 12px 35px #0004;cursor:pointer}
#aocOpsShade{position:fixed;inset:0;background:#0008;z-index:9998;display:none;padding:18px;overflow:auto}.aoc-ops-modal{max-width:920px;margin:3vh auto;background:#fff;color:#111;border-radius:20px;overflow:hidden;box-shadow:0 30px 80px #0006}.aoc-ops-head{display:flex;justify-content:space-between;align-items:center;padding:18px 20px;border-bottom:1px solid #eee}.aoc-ops-tabs{display:flex;gap:8px;padding:12px 16px;border-bottom:1px solid #eee;overflow:auto}.aoc-ops-tabs button{border:1px solid #ddd;background:#fff;border-radius:10px;padding:9px 12px;white-space:nowrap}.aoc-ops-tabs button.active{background:#111;color:#fff}.aoc-ops-body{padding:18px}.aoc-scan-video{width:100%;max-height:420px;object-fit:cover;border-radius:16px;background:#111}.aoc-scan-actions{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.aoc-card{border:1px solid #e8e8e8;border-radius:15px;padding:14px;margin-top:12px}.aoc-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}.aoc-kpi{padding:14px;border-radius:13px;background:#f5f5f5}.aoc-kpi b{display:block;font-size:20px;margin-top:4px}.aoc-history{display:grid;gap:8px}.aoc-history-row{display:flex;justify-content:space-between;gap:12px;padding:10px;border-bottom:1px solid #eee}.aoc-close{border:0;background:transparent;font-size:24px;cursor:pointer}.aoc-muted{color:#666}.aoc-danger{color:#b00020}.aoc-success{color:#087a3d}@media(max-width:600px){#aocOpsBtn{right:12px;bottom:12px}.aoc-ops-modal{margin:0 auto;border-radius:16px}.aoc-ops-body{padding:12px}}
`;document.head.appendChild(s)}
  function modal(){let shade=document.getElementById('aocOpsShade'); if(shade)return shade; shade=document.createElement('div');shade.id='aocOpsShade';shade.innerHTML=`<div class="aoc-ops-modal"><div class="aoc-ops-head"><div><b>🚀 AOC Operations</b><div class="aoc-muted">Member • Barang • Pengembalian • Riwayat</div></div><button class="aoc-close" id="aocOpsClose">×</button></div><div class="aoc-ops-tabs"><button data-op-tab="member">📷 Scan Member</button><button data-op-tab="item">📦 Scan Barang</button><button data-op-tab="return">↩️ Pengembalian</button><button data-op-tab="dashboard">📊 Member 360</button></div><div class="aoc-ops-body" id="aocOpsBody"></div></div>`;document.body.appendChild(shade);shade.addEventListener('click',e=>{if(e.target===shade)close()});shade.querySelector('#aocOpsClose').onclick=close;shade.querySelectorAll('[data-op-tab]').forEach(b=>b.onclick=()=>renderTab(b.dataset.opTab));return shade}
  function open(tab='member'){ensureStyle();modal().style.display='block';renderTab(tab)}
  function close(){stopCamera();const s=document.getElementById('aocOpsShade');if(s)s.style.display='none'}
  function body(){return document.getElementById('aocOpsBody')}
  function setActive(tab){document.querySelectorAll('#aocOpsShade [data-op-tab]').forEach(b=>b.classList.toggle('active',b.dataset.opTab===tab))}
  function renderTab(tab){setActive(tab);stopCamera();if(tab==='member')renderScanner('member');else if(tab==='item')renderScanner('item');else if(tab==='return')renderReturn();else renderDashboard()}
  function renderScanner(type){body().innerHTML=`<div class="aoc-card"><h3>${type==='member'?'📷 Scan Member':'📦 Scan Barang'}</h3><video id="aocScanVideo" class="aoc-scan-video" playsinline muted></video><div class="aoc-scan-actions"><button class="btn primary" id="aocStartCamera">Buka Kamera</button><button class="btn" id="aocStopCamera">Stop</button><input class="input" id="aocManualCode" placeholder="Masukkan kode QR manual"></div><div id="aocScanResult" class="aoc-card"><span class="aoc-muted">Kamera siap digunakan.</span></div></div>`;document.getElementById('aocStartCamera').onclick=()=>startCamera(type);document.getElementById('aocStopCamera').onclick=stopCamera;document.getElementById('aocManualCode').addEventListener('keydown',e=>{if(e.key==='Enter')lookup(type,e.target.value.trim())})}
  async function startCamera(type){try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Browser tidak mendukung kamera. Gunakan Chrome/Edge terbaru.');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});const v=document.getElementById('aocScanVideo');v.srcObject=stream;await v.play();if('BarcodeDetector' in window){detector=new BarcodeDetector({formats:['qr_code']});scanBusy=false;timer=setInterval(async()=>{if(scanBusy||!v.videoWidth)return;scanBusy=true;try{const codes=await detector.detect(v);if(codes?.length){const raw=codes[0].rawValue||'';if(raw&&raw!==lastCode){lastCode=raw;await lookup(type,raw);}}}catch(e){}finally{scanBusy=false}},300)}else{document.getElementById('aocScanResult').innerHTML='<span class="aoc-muted">Browser ini tidak menyediakan QR detector bawaan. Gunakan kolom kode manual atau Chrome Android terbaru.</span>'}}catch(e){document.getElementById('aocScanResult').innerHTML=`<span class="aoc-danger">Kamera gagal dibuka: ${esc(e.message)}</span><br><small>Pastikan izin kamera diberikan dan halaman dibuka melalui HTTPS atau localhost.</small>`}}
  function stopCamera(){if(timer){clearInterval(timer);timer=null}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}const v=document.getElementById('aocScanVideo');if(v)v.srcObject=null;detector=null;lastCode=''}
  async function lookup(type,raw){const value=String(raw||'').trim().replace(/^.*(?:member|item|asset|code)[=:]/i,'').split(/[?#&]/)[0];if(!value)return;const result=document.getElementById('aocScanResult');if(!window.supabase){result.innerHTML='<span class="aoc-danger">Supabase belum tersedia.</span>';return}result.innerHTML='<div class="aoc-muted">Mencari...</div>';const fn=type==='member'?'aoc_secure_member_lookup':'aoc_secure_item_qr_lookup';const {data,error}=await window.supabase.rpc(fn,{p_code:value});if(error){result.innerHTML=`<div class="aoc-danger">${esc(error.message)}</div>`;return}type==='member'?renderMember(result,data):renderAsset(result,data)}
  function renderMember(el,d){const m=d?.member||{},c=d?.card||{},h=d?.history||[];el.innerHTML=`<div class="aoc-grid"><div class="aoc-kpi">Member<b>${esc(m.full_name||'-')}</b></div><div class="aoc-kpi">Kartu<b>${esc(c.card_number||'-')}</b></div><div class="aoc-kpi">Tier<b>${esc(c.tier||'-')}</b></div><div class="aoc-kpi">Poin<b>${Number(d?.points||0).toLocaleString('id-ID')}</b></div><div class="aoc-kpi">Total Rental/Transaksi<b>${money(d?.total_spent)}</b></div><div class="aoc-kpi">Status<b>${m.is_blocked?'🔴 Diblokir':'🟢 Aktif'}</b></div></div><div class="aoc-card"><b>Profil</b><p>${esc(m.email||'-')}<br>${esc(m.phone||'-')} · ${esc(m.city||'-')}</p></div><div class="aoc-card"><b>Riwayat Rental / Pesanan</b><div class="aoc-history">${h.length?h.map(o=>`<div class="aoc-history-row"><span><b>${esc(o.order_number||'-')}</b><br><small>${esc(o.status||'-')} · ${o.created_at?new Date(o.created_at).toLocaleString('id-ID'):'-'}</small></span><b>${money(o.total)}</b></div>`).join(''):'<span class="aoc-muted">Belum ada transaksi.</span>'}</div></div>`}
  function renderAsset(el,d){const a=d?.asset||{},i=d?.item||{},v=d?.variant,l=d?.location;el.innerHTML=`<div class="aoc-grid"><div class="aoc-kpi">Asset<b>${esc(a.asset_code)}</b></div><div class="aoc-kpi">Barang<b>${esc(i.title)}</b></div><div class="aoc-kpi">Status<b>${esc(a.status)}</b></div><div class="aoc-kpi">Kondisi<b>${esc(a.condition)}</b></div></div><div class="aoc-card"><b>Lokasi</b><p>${esc(l?.name||'Belum ditentukan')} ${v?`· ${esc(v.name)} ${esc(v.capacity||'')}`:''}</p><div class="aoc-scan-actions"><button class="btn" data-asset-status="available">Tersedia</button><button class="btn" data-asset-status="rented">Disewa</button><button class="btn" data-asset-status="maintenance">Maintenance</button><button class="btn" data-asset-status="damaged">Rusak</button></div></div>`;el.querySelectorAll('[data-asset-status]').forEach(b=>b.onclick=async()=>{const {error}=await window.supabase.rpc('aoc_secure_set_asset_status',{p_asset_id:a.id,p_status:b.dataset.assetStatus,p_condition:null,p_notes:null});if(error)toast(error.message,'error');else{toast('Status barang diperbarui','success');lookup('item',a.asset_code)}})}
  function renderReturn(){body().innerHTML=`<div class="aoc-card"><h3>↩️ Pengembalian</h3><p class="aoc-muted">Scan QR member atau masukkan nomor pesanan untuk menemukan rental aktif.</p><input class="input" id="aocReturnCode" placeholder="AOC-MBR-... atau nomor pesanan"><div class="aoc-scan-actions"><button class="btn primary" id="aocReturnFind">Cari</button><button class="btn" id="aocReturnCamera">📷 Scan Member</button></div><div id="aocReturnResult"></div></div>`;document.getElementById('aocReturnFind').onclick=()=>findReturn(document.getElementById('aocReturnCode').value.trim());document.getElementById('aocReturnCamera').onclick=()=>renderScanner('member')}
  async function findReturn(code){if(!code)return;const el=document.getElementById('aocReturnResult');const {data,error}=await window.supabase.rpc('aoc_secure_member_lookup',{p_code:code});if(error){el.innerHTML=`<div class="aoc-danger">${esc(error.message)}</div>`;return}const h=(data?.history||[]).filter(x=>!['cancelled','completed'].includes(String(x.status||'').toLowerCase()));el.innerHTML=`<div class="aoc-card"><b>Rental aktif</b>${h.length?h.map(o=>`<div class="aoc-history-row"><span>${esc(o.order_number)}<br><small>${esc(o.status)} · ${o.rental_start||'-'} → ${o.rental_end||'-'}</small></span><button class="btn" disabled title="Gunakan Finalisasi/Pengembalian yang sudah ada di Admin Panel">Buka</button></div>`).join(''):'<p class="aoc-muted">Tidak ada rental aktif.</p>'}</div>`}
  async function renderDashboard(){body().innerHTML='<div class="notice">Memuat Member 360...</div>';const {data,error}=await window.supabase.rpc('secure_list_customers');if(error){body().innerHTML=`<div class="aoc-danger">${esc(error.message)}</div>`;return}const total=(data||[]).length,verified=(data||[]).filter(x=>x.is_verified).length,blocked=(data||[]).filter(x=>x.is_blocked).length,spent=(data||[]).reduce((s,x)=>s+Number(x.total_spent||0),0);body().innerHTML=`<div class="aoc-grid"><div class="aoc-kpi">Member<b>${total}</b></div><div class="aoc-kpi">Terverifikasi<b>${verified}</b></div><div class="aoc-kpi">Diblokir<b>${blocked}</b></div><div class="aoc-kpi">Total transaksi<b>${money(spent)}</b></div></div><div class="aoc-card"><b>Member terbesar berdasarkan transaksi</b>${(data||[]).slice(0,10).map(x=>`<div class="aoc-history-row"><span>${esc(x.full_name||x.email)}<br><small>${Number(x.total_orders||0)} pesanan</small></span><b>${money(x.total_spent)}</b></div>`).join('')}</div>`}
  function boot(){ensureStyle();const b=document.createElement('button');b.id='aocOpsBtn';b.textContent='🚀 AOC Operations';b.onclick=()=>open('member');document.body.appendChild(b)}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
